-- Synthetic schema4 extension; original schema3 SQL above is byte-preserved.
BEGIN IMMEDIATE;
CREATE TABLE preference_control (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 library_id TEXT NOT NULL REFERENCES catalog(library_id),
 clock_floor_unix INTEGER NOT NULL CHECK(clock_floor_unix>=0),
 subject_count INTEGER NOT NULL CHECK(subject_count BETWEEN 0 AND 1024),
 entry_count INTEGER NOT NULL CHECK(entry_count BETWEEN 0 AND 65536),
 receipt_count INTEGER NOT NULL CHECK(receipt_count BETWEEN 0 AND 32768)
);
CREATE TABLE preference_receipts (
 subject_id TEXT NOT NULL REFERENCES preference_subjects(subject_id),
 operation_id TEXT NOT NULL CHECK(length(operation_id) BETWEEN 1 AND 128 AND operation_id NOT GLOB '*[^a-zA-Z0-9_-]*'),
 request BLOB NOT NULL CHECK(typeof(request)='blob' AND length(request) BETWEEN 1 AND 1024),
 payload_sha256 TEXT NOT NULL CHECK(length(payload_sha256)=64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'),
 receipt BLOB NOT NULL CHECK(typeof(receipt)='blob' AND length(receipt) BETWEEN 1 AND 512),
 expires_unix INTEGER NOT NULL CHECK(expires_unix>0),
 PRIMARY KEY(subject_id,operation_id)
);
CREATE TABLE preference_subjects (
 subject_id TEXT PRIMARY KEY NOT NULL REFERENCES policy_subjects(subject_id),
 library_id TEXT NOT NULL REFERENCES catalog(library_id),
 generation INTEGER NOT NULL CHECK(generation>0),
 entry_count INTEGER NOT NULL CHECK(entry_count BETWEEN 0 AND 256),
 receipt_count INTEGER NOT NULL CHECK(receipt_count BETWEEN 0 AND 128)
);
CREATE TABLE preferences (
 subject_id TEXT NOT NULL REFERENCES preference_subjects(subject_id),
 asset_id TEXT NOT NULL REFERENCES assets(asset_id),
 selection_token TEXT NOT NULL UNIQUE CHECK(length(selection_token)=69 AND substr(selection_token,1,5)='sel1_' AND substr(selection_token,6) NOT GLOB '*[^0-9a-f]*'),
 person_order INTEGER NOT NULL CHECK(person_order>0),
 selected_unix INTEGER NOT NULL CHECK(selected_unix>=0 AND selected_unix<=9223372036852183807),
 expires_unix INTEGER NOT NULL CHECK(expires_unix=selected_unix+2592000),
 PRIMARY KEY(subject_id,asset_id),
 UNIQUE(subject_id,person_order)
);
CREATE INDEX preference_receipts_expiry ON preference_receipts(expires_unix,subject_id,operation_id);
CREATE INDEX preference_receipts_subject_expiry ON preference_receipts(subject_id,expires_unix,operation_id);
CREATE INDEX preferences_expiry ON preferences(expires_unix,subject_id,asset_id);
CREATE INDEX preferences_recent ON preferences(subject_id,person_order DESC,asset_id);
CREATE TRIGGER preference_control_identity BEFORE UPDATE ON preference_control WHEN NEW.singleton<>OLD.singleton OR NEW.library_id<>OLD.library_id OR NEW.clock_floor_unix<OLD.clock_floor_unix BEGIN SELECT RAISE(ABORT,'preference control identity'); END;
CREATE TRIGGER preference_control_no_delete BEFORE DELETE ON preference_control BEGIN SELECT RAISE(ABORT,'preference control lifetime'); END;
CREATE TRIGGER preference_receipts_delete AFTER DELETE ON preference_receipts BEGIN UPDATE preference_subjects SET receipt_count=receipt_count-1 WHERE subject_id=OLD.subject_id; UPDATE preference_control SET receipt_count=receipt_count-1 WHERE singleton=1; END;
CREATE TRIGGER preference_receipts_delete_guard BEFORE DELETE ON preference_receipts WHEN OLD.expires_unix>(SELECT clock_floor_unix FROM preference_control WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'unexpired preference receipt'); END;
CREATE TRIGGER preference_receipts_insert AFTER INSERT ON preference_receipts BEGIN UPDATE preference_subjects SET receipt_count=receipt_count+1 WHERE subject_id=NEW.subject_id; UPDATE preference_control SET receipt_count=receipt_count+1 WHERE singleton=1; END;
CREATE TRIGGER preference_receipts_no_update BEFORE UPDATE ON preference_receipts BEGIN SELECT RAISE(ABORT,'immutable preference receipt'); END;
CREATE TRIGGER preference_subjects_identity BEFORE UPDATE ON preference_subjects WHEN NEW.subject_id<>OLD.subject_id OR NEW.library_id<>OLD.library_id OR NEW.generation<OLD.generation OR (NEW.generation<>OLD.generation AND NEW.generation<>OLD.generation+1) BEGIN SELECT RAISE(ABORT,'preference generation identity'); END;
CREATE TRIGGER preference_subjects_insert AFTER INSERT ON preference_subjects BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM policy_subjects WHERE subject_id=NEW.subject_id AND library_id=NEW.library_id AND kind='person') THEN RAISE(ABORT,'preference person membership') END; UPDATE preference_control SET subject_count=subject_count+1 WHERE singleton=1; END;
CREATE TRIGGER preference_subjects_no_delete BEFORE DELETE ON preference_subjects BEGIN SELECT RAISE(ABORT,'preference generation lifetime'); END;
CREATE TRIGGER preferences_delete AFTER DELETE ON preferences BEGIN UPDATE preference_subjects SET entry_count=entry_count-1 WHERE subject_id=OLD.subject_id; UPDATE preference_control SET entry_count=entry_count-1 WHERE singleton=1; END;
CREATE TRIGGER preferences_identity BEFORE UPDATE ON preferences WHEN NEW.subject_id<>OLD.subject_id OR NEW.asset_id<>OLD.asset_id OR NEW.selection_token=OLD.selection_token OR NEW.person_order<=OLD.person_order BEGIN SELECT RAISE(ABORT,'preference replacement identity'); END;
CREATE TRIGGER preferences_insert AFTER INSERT ON preferences BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM preference_subjects p JOIN assets a ON a.library_id=p.library_id WHERE p.subject_id=NEW.subject_id AND a.asset_id=NEW.asset_id AND p.generation=NEW.person_order) THEN RAISE(ABORT,'preference membership') END; UPDATE preference_subjects SET entry_count=entry_count+1 WHERE subject_id=NEW.subject_id; UPDATE preference_control SET entry_count=entry_count+1 WHERE singleton=1; END;
CREATE TRIGGER preferences_order AFTER UPDATE ON preferences WHEN NEW.person_order<>(SELECT generation FROM preference_subjects WHERE subject_id=NEW.subject_id) BEGIN SELECT RAISE(ABORT,'preference order'); END;
